/// <summary>
/// application matches the executable or package name exactly (the comparison is
/// case-insensitive for Windows executables and exact for Android package names);
/// title_keyword matches when the local window title contains the keyword
/// case-insensitively; title_regex matches the local window title against a regular
/// expression, which is the only way to extract a candidate project name.
/// </summary>
public enum ClassificationRuleKind { Application, TitleKeyword, TitleRegex };

/// <summary>
/// Collector platform the rule applies to; any applies everywhere. Title rules are only
/// executable on platforms that observe window titles.
/// </summary>
public enum ClassificationRulePlatform { Android, Any, Windows };

/// <summary>
/// Service entities name a cross-platform service (a browser session and a native package
/// can both map to one service subject); project entities name an Owner-approved project
/// alias used to separate work time, for example per-project IDE activity.
/// </summary>
public enum SemanticEntityKind { Project, Service };

/// <summary>
/// Actor type the credential authenticates: a device collector uploads events, a query agent
/// reads approved data domains.
/// </summary>
public enum CredentialKind { DeviceToken, QueryToken };

/// <summary>
/// Maximum privacy level the credential may touch, ordered normal &lt; sensitive &lt; private.
/// Uploads above the ceiling are rejected per item; reads exclude data above the ceiling.
/// </summary>
public enum CredentialPrivacyCeiling { Normal, Private, Sensitive };

/// <summary>
/// Capability granted to the credential. Scopes are domain-scoped: events:write,
/// health:write, and payment:write restrict which event domains a device token may upload
/// (activity intervals, Health Connect observations, payment transactions), while
/// events:read, health:read, and payment:read restrict which domains a query token may read.
/// rules:read lets a device token download the classification rule set so it can classify
/// locally; it is device-only, because rule distribution is a collector concern and the
/// management plane stays with the Owner session. A credential never holds a scope outside
/// its actor type.
/// </summary>
public enum CredentialScope { EventsRead, EventsWrite, HealthRead, HealthWrite, PaymentRead, PaymentWrite, RulesRead };

/// <summary>
/// Collector platform the heartbeat originates from.
///
/// Collector platform the device reported its events with.
///
/// Collector platform the snapshot originates from.
/// </summary>
public enum Platform { Android, Windows };

public enum EventType { ActivityInterval, HealthHeartrateSample, HealthSleepSession, HealthStepSample, PaymentTransaction };

public enum FinalizationState { Checkpoint, Final };

/// <summary>
/// Spending category produced by on-device classification rules over the merchant label.
/// </summary>
public enum Category { Bills, Education, Entertainment, Food, Health, Shopping, Transfer, Transport, Uncategorized };

public enum StepUnit { Steps };

/// <summary>
/// Whether the transaction credited (income) or debited (expense) the Owner.
/// </summary>
public enum Direction { Expense, Income };

public enum DurationUnit { Ms };

/// <summary>
/// Private observations are blocked on-device and cannot enter this contract.
///
/// Health observations default to sensitive; credentials need an adequate privacy ceiling to
/// upload or read them.
///
/// Financial observations default to sensitive; credentials need an adequate privacy ceiling
/// to upload or read them.
/// </summary>
public enum PrivacyLevel { Normal, Sensitive };

/// <summary>
/// Collector mechanism that observed the interval. UsageStats is the authoritative source
/// for Android daily application totals; accessibility observations only support current and
/// contextual activity.
///
/// Health Connect records read by the Android collector. The origin application inside each
/// payload is the data origin; the collector itself is only the transport.
///
/// Payment notifications parsed by the Android collector; the collector extracts structured
/// fields locally and the raw notification never leaves the device.
/// </summary>
public enum SourceKind { AndroidAccessibility, AndroidHealthconnect, AndroidUsagestats, AndroidWechatpay, WindowsForeground };

public enum EventAcknowledgementStatus { Accepted, Duplicate, Rejected, StaleRevision };

public enum Completeness { Complete, Partial, Unknown };

/// <summary>
/// Presence semantics for the queried range, so a report never reads as a bare number:
/// observed means in-range observations produced the reported values; zero means
/// observations exist but the normalized value is explicitly 0; no_data means the range
/// holds no observations at all. Partial coverage is reported by completeness and competing
/// sources by source_conflicts.
/// </summary>
public enum DataState { NoData, Observed, Zero };

public enum ReclassificationTaskStatusStatus { Closed, Open };

